41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
43	
44	const BASE_PREMIUMS: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
54	const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);
55	
56	const COMPONENT_BLOCK_SIZE = 3;
57	const COMPONENT_BLOCK_PREMIUM = 60;
58	
59	const countsByType = (items: Item[]): Map<string, number> => {
60	  const counts = new Map<string, number>();
61	  for (const item of items) {
62	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
63	  }
64	  return counts;
65	};
66	
67	const policyBasePremiumOf = (items: Item[]): number => {
68	  let total = 0;
69	  for (const [type, count] of countsByType(items)) {
70	    total +=
71	      count === COMPONENT_BLOCK_SIZE
72	        ? COMPONENT_BLOCK_PREMIUM
73	        : count * BASE_PREMIUMS[type];
74	  }
75	  return total;
76	};
77	
78	const quote = (step: QuoteStep): StepResult => {
79	  const policyBasePremium = policyBasePremiumOf(step.items);
80	  return {
81	    premium: roundPremiumInMHPCOFavour(
82	      policyBasePremium +
83	        policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE +
84	        PROCESSING_FEE,
85	    ),
86	  };
87	};
88	
89	const runStep = (step: Step): StepResult => {
90	  if (step.op === "quote") return quote(step);
91	  throw new Error(`Unsupported step: ${step.op}`);
92	};
93	
94	export const runScenario = (scenario: Scenario): ScenarioResult => ({
95	  results: scenario.steps.map(runStep),
96	});
