const countsByType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
    new Map<string, number>(),
  );

/** A group of exactly three alike items is a building block, priced at a flat rate. */
const basePremiumForGroup = (type: string, count: number): number =>
  count === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM
    : count * BASE_PREMIUMS[type];

const policyBasePremiumOf = (items: Item[]): number =>
  [...countsByType(items)].reduce(
    (total, [type, count]) => total + basePremiumForGroup(type, count),
    0,
  );
